import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Panel rápido (Configuración)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/quick-panel.md","filePath":"es-ES/user-guide/settings/quick-panel.md","lastUpdated":1787586465000}'),i={name:"es-ES/user-guide/settings/quick-panel.md"};function s(n,e,l,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="panel-rapido-configuracion" tabindex="-1">Panel rápido (Configuración) <a class="header-anchor" href="#panel-rapido-configuracion" aria-label="Permalink to &quot;Panel rápido (Configuración)&quot;">​</a></h1><p>El <strong>Panel rápido (Quick Panel)</strong> es un espacio de trabajo flotante diseñado para la consulta rápida de archivos, la gestión del contexto de proyectos y el depósito de archivos mediante arrastrar y soltar. Al invocarse, se acopla automáticamente a la esquina inferior derecha de la ventana activa, permitiéndote acceder y preparar archivos sin cambiar de contexto.</p><h2 id="_1-mecanismo-central-e-interruptor-general" tabindex="-1">1. Mecanismo central e interruptor general <a class="header-anchor" href="#_1-mecanismo-central-e-interruptor-general" aria-label="Permalink to &quot;1. Mecanismo central e interruptor general&quot;">​</a></h2><ul><li><strong>Habilitar Panel rápido</strong>: Interruptor maestro; cuando está desactivado, el atajo deja de interceptar pulsaciones.</li><li><strong>Atajo de invocación</strong>: Por defecto <strong><code>Ctrl+F2</code></strong> (personalizable en <a href="./hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>).</li><li><strong>Acoplamiento inteligente y dimensiones</strong>: Se ajusta por defecto a la mitad del ancho y alto de la ventana anfitriona (con un tamaño mínimo de <code>280 × 200px</code> para asegurar la legibilidad). Si una ventana de Lertaro ya tiene el foco, la invocación se ignora para no apilar ventanas; si el panel ya está abierto, el mismo atajo lo cierra.</li><li><strong>Integración con Salto rápido</strong>: Mientras el panel está abierto, la carpeta física del grupo seleccionado se registra como directorio de trabajo. Al pulsar Salto rápido (<code>Ctrl+G</code>) en cuadros de diálogo de archivos, se navegará directamente hasta ella.</li></ul><h2 id="_2-espacios-de-trabajo-workspaces" tabindex="-1">2. Espacios de trabajo (Workspaces) <a class="header-anchor" href="#_2-espacios-de-trabajo-workspaces" aria-label="Permalink to &quot;2. Espacios de trabajo (Workspaces)&quot;">​</a></h2><p>Permiten organizar carpetas por proyecto o tarea:</p><ul><li><strong>Gestión de espacios de trabajo</strong>: La lista izquierda permite <strong>Crear</strong>, <strong>Duplicar</strong> y <strong>Eliminar</strong>, con ordenación por arrastre que se refleja en la barra de pestañas.</li><li><strong>Propiedades</strong>: <ul><li><strong>Nombre</strong>: Texto de la pestaña (usa el nombre predeterminado localizado si se deja en blanco).</li><li><strong>Interruptor de activación</strong>: Controla la presencia de la pestaña en la barra. Pulsar <strong>×</strong> en una pestaña del panel la oculta; se puede volver a activar aquí.</li></ul></li></ul><p>Los espacios de trabajo seleccionados se configuran en dos pestañas: <strong>Orígenes</strong> y <strong>Aplicaciones</strong>.</p><h2 id="_3-configuracion-de-origenes-sources" tabindex="-1">3. Configuración de orígenes (Sources) <a class="header-anchor" href="#_3-configuracion-de-origenes-sources" aria-label="Permalink to &quot;3. Configuración de orígenes (Sources)&quot;">​</a></h2><p>Cada origen representa un grupo independiente dentro del espacio de trabajo:</p><ul><li><strong>Añadir carpeta</strong>: Selecciona el directorio en disco.</li><li><strong>Modo de visualización</strong>: <ul><li><strong>Archivos modificados recientemente</strong> —— Consulta el índice en memoria en submilisegundos para mostrar cambios recientes (los más nuevos primero).</li><li><strong>Todos los archivos, más recientes primero</strong> —— Muestra todos los archivos ordenados por fecha de modificación descendente.</li><li><strong>Todos los archivos, por nombre</strong> —— Funciona como una barra fija de accesos directos.</li></ul></li><li><strong>Incluir subcarpetas</strong>: Incluye archivos descendientes de forma recursiva.</li><li><strong>Aceptar archivos arrastrados</strong>: Permite arrastrar archivos, carpetas o imágenes web desde otras ventanas. Lertaro ejecuta una copia nativa de Windows con avisos de conflicto y opción de deshacer.</li><li><strong>Reglas de filtrado</strong>: Filtra las extensiones visibles mediante comodines (p. ej. <code>*.mp4;*.mkv</code> o <code>*.pdf;*.docx</code>).</li><li><strong>Límite de elementos y tiempo</strong>: Restringe la cantidad máxima visible (0 para ilimitado) o muestra solo archivos modificados en los últimos N minutos.</li><li><strong>Lista detallada frente a mosaico de miniaturas</strong>: Escoge entre vista de lista compacta o cuadrícula de miniaturas (las miniaturas escalan proporcionalmente conservando su formato original).</li></ul><h2 id="_4-pestanas-de-plugins-plugin-tabs" tabindex="-1">4. Pestañas de plugins (Plugin Tabs) <a class="header-anchor" href="#_4-pestanas-de-plugins-plugin-tabs" aria-label="Permalink to &quot;4. Pestañas de plugins (Plugin Tabs)&quot;">​</a></h2><p>Los plugins pueden registrar listas dinámicas globales en el Panel rápido. El plugin CoreExtensions incluye cinco pestañas predefinidas:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Pestaña de plugin</th><th style="text-align:left;">Contenido</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Favoritos</strong></td><td style="text-align:left;">Elementos destacados con estrella; las URLs se abren en el navegador predeterminado.</td></tr><tr><td style="text-align:left;"><strong>Historial</strong></td><td style="text-align:left;">Elementos y aplicaciones ejecutados recientemente mediante Lertaro.</td></tr><tr><td style="text-align:left;"><strong>Historial de Windows</strong></td><td style="text-align:left;">Resuelve los Documentos recientes de Windows en rutas físicas reales.</td></tr><tr><td style="text-align:left;"><strong>Última carpeta</strong></td><td style="text-align:left;">Rastrea la carpeta recién visitada en el Explorador o en cuadros de diálogo.</td></tr><tr><td style="text-align:left;"><strong>Archivos recientes</strong></td><td style="text-align:left;">Agrupa los archivos más nuevos de todas las carpetas configuradas usando el índice.</td></tr></tbody></table><p>Cada pestaña de plugin se puede activar/desactivar y configurar en modo Lista o Mosaico.</p><h2 id="_5-vinculacion-con-aplicaciones-y-lista-negra" tabindex="-1">5. Vinculación con aplicaciones y lista negra <a class="header-anchor" href="#_5-vinculacion-con-aplicaciones-y-lista-negra" aria-label="Permalink to &quot;5. Vinculación con aplicaciones y lista negra&quot;">​</a></h2><ul><li><strong>Aplicaciones</strong>: Asocia nombres de procesos (p. ej. <code>chrome.exe</code> o <code>devenv.exe</code>) al espacio de trabajo. Al invocar el panel sobre estas aplicaciones, se abrirá directamente el espacio de trabajo correspondiente.</li><li><strong>Lista negra exclusiva del Panel rápido</strong>: Lista de procesos sobre los que no debe aparecer el panel. Se <strong>suma</strong> a la lista negra global de atajos.</li></ul><h2 id="_6-guia-de-uso-e-interaccion" tabindex="-1">6. Guía de uso e interacción <a class="header-anchor" href="#_6-guia-de-uso-e-interaccion" aria-label="Permalink to &quot;6. Guía de uso e interacción&quot;">​</a></h2><ul><li><strong>Filtrado difuso en vivo</strong>: La barra de búsqueda superior derecha admite coincidencia difusa fzf y alias de pinyin para filtrar el espacio de trabajo activo.</li><li><strong>Navegación fluida por teclado</strong>: Las flechas de dirección navegan fluidamente entre grupos; pulsa <code>Enter</code> para abrir el elemento resaltado.</li><li><strong>Cambio de pestañas</strong>: Pulsa <code>Ctrl</code> + <code>1</code>–<code>9</code> para alternar rápidamente entre pestañas de espacios de trabajo y plugins.</li><li><strong>QuickLook y fijación</strong>: Pulsa <code>Alt+P</code> para abrir la vista previa acoplada; pulsa <code>Ctrl+T</code> para fijar el panel y evitar que se cierre al perder el foco.</li></ul>',19)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
